import React from 'react';
import Modal from "../../Templates/Modal/Modal";
import axios from "axios";


function Role({modalActiveRole,setModalActiveRole,username}) {



    return (
        <Modal active={modalActiveRole} setActive={setModalActiveRole}>
            <h1>Изменение информации:</h1>
            <hr/>
            <h2>Новый пароль будет: qwerty123</h2>
            <button className="ModalButtonRePasswordUser" type="submit" onClick={handleResetPassword}>
                Сбросить
            </button>
        </Modal>
    );

}

export default Role;
